from pathlib import Path
ROOT=Path('/workspace/app/docs/states/baselines/document-workshop')
d=json.loads((ROOT/'frida-v1-document-workshop-p2-m4-01-20261006.json').read_text())
original=json.loads(Path('/proof/original-p2-m4-01.json').read_text())
old=original['new_sql_test_ids']; module='tests.integration.document_workshop.test_action_cancellation_postgresql'
def flatten(s):
 for t in s:
  if isinstance(t,unittest.TestSuite): yield from flatten(t)
  else: yield t
loader=unittest.TestLoader(); cases=list(flatten(loader.loadTestsFromName(module)))
assert not loader.errors
ids=[t.id() for t in cases]; assert len(ids)==len(set(ids))==21
bad=[]
for value in old:
 l=unittest.TestLoader(); s=l.loadTestsFromName(value)
 bad.append({'id':value,'loading_errors':len(l.errors),'loaded_test_placeholders':s.countTestCases()})
