assert [x.rsplit('.',1)[0] for x in old]==ids
assert d['new_sql_test_ids']==ids
rows=[]
for value in ids:
 l=unittest.TestLoader(); loaded=list(flatten(l.loadTestsFromName(value)))
 assert not l.errors and len(loaded)==1 and loaded[0].id()==value
 assert loaded[0]._testMethodName==value.rsplit('.',1)[1]
 rows.append({'id':value,'loaded_tests':len(loaded),'loading_errors':len(l.errors),'method_name':loaded[0]._testMethodName,'id_preserved':True})
def digest(values): return hashlib.sha256(('\n'.join(sorted(set(values)))+'\n').encode()).hexdigest()
sel_loader=unittest.TestLoader(); all_ids=[]
for s in d['final']['sql']['selectors']: all_ids.extend(t.id() for t in flatten(sel_loader.loadTestsFromName(s)))
assert not sel_loader.errors and len(all_ids)==len(set(all_ids))==142
other=json.loads((ROOT/'frida-v1-document-workshop-p2-m4-02-20261006.json').read_text())
# Inspect every list carrying executable IDs; the corrected module must match all historical successful lists.
success_lists=[]
def scan(obj,path):
 if isinstance(obj,dict):
  for k,v in obj.items(): scan(v,path+'.'+k)
 elif isinstance(obj,list):
  if obj and all(isinstance(x,str) for x in obj):
   found=[x for x in obj if x.startswith(module+'.')]
   if found: success_lists.append({'path':path,'case_count':len(found),'same_21_cases':set(found)==set(ids)})
  else:
   for i,v in enumerate(obj):scan(v,path+'['+str(i)+']')
assert all_ids==other['baseline']['selections']['sql']['test_ids']
